create extension if not exists pgcrypto;
create type public.tour_status as enum ('draft','published','live','completed');
create type public.player_status as enum ('invited','active','withdrawn');
create type public.round_format as enum ('singles','betterball','scramble_drive','alternate_shot');
create type public.handicap_mode as enum ('FULL','PLAY_OFF_LOWEST','SCRATCH');
create type public.round_status as enum ('scheduled','live','suspended','completed','void');
create type public.match_status as enum ('scheduled','live','decided','awaiting_confirmation','confirmed','void');
create type public.scorecard_status as enum ('not_started','in_progress','complete');
create type public.result_type as enum ('NORMAL','CONCESSION','VOID');
create type public.score_status as enum ('NORMAL','OVERFLOW','CONCESSION');
create type public.invitation_status as enum ('pending','claimed','revoked','expired');
create type public.match_side as enum ('A','B');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tours (id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name))>0),start_date date not null,end_date date not null,status public.tour_status not null default 'draft',organiser_user_id uuid not null references public.profiles(id),spectator_slug text unique,spectator_enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table public.teams (id uuid primary key default gen_random_uuid(),tour_id uuid not null references public.tours(id) on delete cascade,name text not null,colour text not null,logo_url text,created_at timestamptz not null default now(),unique(tour_id,name));
create table public.tour_players (id uuid primary key default gen_random_uuid(),tour_id uuid not null references public.tours(id) on delete cascade,user_id uuid references public.profiles(id),team_id uuid not null references public.teams(id),display_name text not null,frozen_handicap_index numeric(4,1),status public.player_status not null default 'invited',created_at timestamptz not null default now(),unique(tour_id,user_id));
create table public.courses (id uuid primary key default gen_random_uuid(),name text not null,province text,golf_union text,latitude numeric(9,6),longitude numeric(9,6),source_name text,source_url text,verified_at timestamptz,verification_status text not null default 'unverified',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.course_tees (id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,tee_name text not null,gender_rating text,course_rating numeric(4,1) not null,slope_rating integer not null check(slope_rating between 55 and 155),par integer not null check(par between 27 and 90),total_metres integer,source_url text,verified_at timestamptz,unique(course_id,tee_name,gender_rating));
create table public.course_holes (id uuid primary key default gen_random_uuid(),course_tee_id uuid not null references public.course_tees(id) on delete cascade,hole_number integer not null check(hole_number between 1 and 18),par integer not null check(par between 3 and 6),stroke_index integer not null check(stroke_index between 1 and 18),metres integer,unique(course_tee_id,hole_number),unique(course_tee_id,stroke_index));
create table public.rounds (id uuid primary key default gen_random_uuid(),tour_id uuid not null references public.tours(id) on delete cascade,round_number integer not null check(round_number>0),round_date date not null,course_id uuid not null references public.courses(id),course_tee_id uuid not null references public.course_tees(id),format public.round_format not null,handicap_mode public.handicap_mode not null default 'FULL',hole_start integer not null default 1 check(hole_start between 1 and 18),hole_end integer not null default 18 check(hole_end between 1 and 18),first_tee_time time,points_per_match numeric(5,2) not null default 1 check(points_per_match>0),status public.round_status not null default 'scheduled',created_at timestamptz not null default now(),unique(tour_id,round_number),check(hole_end>=hole_start));
create table public.round_course_snapshots (round_id uuid primary key references public.rounds(id) on delete cascade,course_name text not null,tee_name text not null,course_rating numeric(4,1) not null,slope_rating integer not null,par integer not null,captured_at timestamptz not null default now());
create table public.round_hole_snapshots (round_id uuid not null references public.rounds(id) on delete cascade,hole_number integer not null check(hole_number between 1 and 18),par integer not null check(par between 3 and 6),stroke_index integer not null check(stroke_index between 1 and 18),metres integer,primary key(round_id,hole_number),unique(round_id,stroke_index));
create table public.round_players (id uuid primary key default gen_random_uuid(),round_id uuid not null references public.rounds(id) on delete cascade,tour_player_id uuid not null references public.tour_players(id),frozen_tour_handicap_index numeric(4,1) not null,course_handicap integer not null,active boolean not null default true,unique(round_id,tour_player_id));
create table public.matches (id uuid primary key default gen_random_uuid(),round_id uuid not null references public.rounds(id) on delete cascade,match_number integer not null check(match_number>0),tee_time time,format public.round_format not null,points_value numeric(5,2) not null default 1 check(points_value>0),status public.match_status not null default 'scheduled',match_decided_at_hole integer check(match_decided_at_hole between 1 and 18),scorecard_status public.scorecard_status not null default 'not_started',result_type public.result_type,created_at timestamptz not null default now(),unique(round_id,match_number));
create table public.match_participants (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,tour_player_id uuid not null references public.tour_players(id),team_id uuid not null references public.teams(id),side public.match_side not null,pair_position integer,unique(match_id,tour_player_id));
create table public.match_handicaps (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,tour_player_id uuid references public.tour_players(id),team_id uuid references public.teams(id),handicap_index numeric(4,1),course_handicap integer,format_handicap integer not null,match_handicap integer not null,check(tour_player_id is not null or team_id is not null));
create table public.hole_scores (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,round_id uuid not null references public.rounds(id) on delete cascade,hole_number integer not null check(hole_number between 1 and 18),tour_player_id uuid not null references public.tour_players(id),gross_score integer not null check(gross_score>=1),score_status public.score_status not null default 'NORMAL',version integer not null default 1 check(version>0),entered_by_user_id uuid not null references public.profiles(id),client_event_id uuid not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(match_id,hole_number,tour_player_id));
create table public.team_hole_scores (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,team_id uuid not null references public.teams(id),hole_number integer not null check(hole_number between 1 and 18),gross_score integer not null check(gross_score>=1),score_status public.score_status not null default 'NORMAL',version integer not null default 1 check(version>0),entered_by_user_id uuid not null references public.profiles(id),client_event_id uuid not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(match_id,team_id,hole_number));
create table public.selected_drives (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,hole_number integer not null check(hole_number between 1 and 18),team_id uuid not null references public.teams(id),tour_player_id uuid not null references public.tour_players(id),entered_by_user_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(match_id,hole_number,team_id));
create table public.alternate_shot_settings (match_id uuid not null references public.matches(id) on delete cascade,team_id uuid not null references public.teams(id),odd_hole_tee_player_id uuid not null references public.tour_players(id),even_hole_tee_player_id uuid not null references public.tour_players(id),primary key(match_id,team_id),check(odd_hole_tee_player_id<>even_hole_tee_player_id));
create table public.match_confirmations (match_id uuid primary key references public.matches(id) on delete cascade,result_type public.result_type not null,winning_team_id uuid references public.teams(id),result_display text not null,points_team_a numeric(5,2) not null check(points_team_a>=0),points_team_b numeric(5,2) not null check(points_team_b>=0),confirmed_by_user_id uuid not null references public.profiles(id),confirmed_at timestamptz not null default now(),reopened_by_user_id uuid references public.profiles(id),reopened_at timestamptz);
create table public.invitations (id uuid primary key default gen_random_uuid(),tour_id uuid not null references public.tours(id) on delete cascade,tour_player_id uuid not null references public.tour_players(id) on delete cascade,token_hash text not null unique,status public.invitation_status not null default 'pending',expires_at timestamptz,claimed_by_user_id uuid references public.profiles(id),claimed_at timestamptz,created_at timestamptz not null default now());
create table public.audit_log (id bigserial primary key,tour_id uuid references public.tours(id) on delete cascade,actor_user_id uuid references public.profiles(id),entity_type text not null,entity_id uuid,action text not null,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
create index idx_teams_tour on public.teams(tour_id); create index idx_tour_players_tour on public.tour_players(tour_id); create index idx_tour_players_user on public.tour_players(user_id); create index idx_rounds_tour on public.rounds(tour_id); create index idx_round_players_round on public.round_players(round_id); create index idx_matches_round on public.matches(round_id); create index idx_match_participants_match on public.match_participants(match_id); create index idx_match_participants_player on public.match_participants(tour_player_id); create index idx_hole_scores_match_hole on public.hole_scores(match_id,hole_number); create index idx_team_hole_scores_match_hole on public.team_hole_scores(match_id,hole_number); create index idx_invitations_player on public.invitations(tour_player_id); create index idx_audit_tour_created on public.audit_log(tour_id,created_at desc);
